export function solve(graph) {
  const seen = new Set();
  function visit(node) {
    if (seen.has(node)) return true;
    seen.add(node);
    return (graph[node] || []).some(visit);
  }
  return Object.keys(graph).some(visit);
}

tasks.reference:
export function solve(graph) {
  const done = new Set(), active = new Set();
  function visit(node) {
    if (active.has(node)) return true;
    if (done.has(node)) return false;
    active.add(node);
    for (const child of Object.hasOwn(graph,node) ? graph[node] : []) if (visit(child)) return true;
    active.delete(node); done.add(node); return false;
  }
  return Object.keys(graph).some(visit);
}

