tasks.reference:
export function solve(edges) {
  const graph = new Map();
  for (const [a,b] of edges) {if (!graph.has(a)) graph.set(a,[]);graph.get(a).push(b);}
  const done = new Set(), active = new Set();
  function visit(n) {
    if (active.has(n)) return true;
    if (done.has(n)) return false;
    active.add(n);
    for (const child of graph.get(n) || []) if (visit(child)) return true;
    active.delete(n);done.add(n);return false;
  }
  return [...graph.keys()].some(visit);
}

