export function solve(ids, cursor, limit) {
  const start = cursor === null ? 0 : ids.indexOf(cursor) + 1;
  return ids.slice(start,start + limit);
}

tasks.reference:
export function solve(ids, cursor, limit) {
  if (cursor === null) return ids.slice(0,limit);
  const index = ids.indexOf(cursor);
  return index < 0 ? [] : ids.slice(index+1,index+1+limit);
}
